/** Shape of one entry of odoo/odoo/tools/partner_identifiers.py metadata, as generated by gen_tables.py. */
export type IdentifierValue =
  | string | number | boolean | null
  | readonly IdentifierValue[]
  /** A LazyGettext (`_lt(...)`): resolved with the env language at read time (res_partner.py:1655). */
  | { readonly kind: "lazy"; readonly source: string }
  /** A validation/format function: Odoo leaks `repr()` of it, `<function NAME at 0x...>` (harness N3). */
  | { readonly kind: "function"; readonly name: string };

export type IdentifierMetadata = Readonly<Record<string, IdentifierValue>>;
